-- Migration: 20261016000900_fan_card_variants.sql
-- Additional illustrations belong to one original fan card, not a new card row.
create table public.fan_card_variants (
  fan_card_id uuid not null references public.fan_cards(id) on delete cascade,
  artwork_id text not null unique check (artwork_id ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
  label text not null check (length(btrim(label)) between 1 and 100),
  created_at timestamptz not null default now(),
  primary key(fan_card_id, artwork_id)
);
alter table public.fan_card_variants enable row level security;
revoke all on public.fan_card_variants from anon, authenticated;
grant select on public.fan_card_variants to authenticated;
create policy fan_card_variants_authenticated_read on public.fan_card_variants
  for select to authenticated using ((select auth.uid()) is not null);

insert into public.fan_card_variants(fan_card_id,artwork_id,label)
values('d515ca79-15ba-4f9f-b730-d5fba7f27a07','su-d-yoyi-awakening','Arte alternativo');

INSERT INTO supabase_migrations.schema_migrations(version, name) VALUES ('20261016000900', 'fan_card_variants');

-- Migration: 20261016001000_fan_card_unlocks.sql
-- Discoveries are private, durable and append-only for ordinary accounts.
create table public.fan_card_unlocks (
  user_id uuid not null default auth.uid() references auth.users(id) on delete cascade,
  fan_card_id uuid not null references public.fan_cards(id) on delete cascade,
  unlocked_at timestamptz not null default now(),
  primary key (user_id, fan_card_id)
);
create index fan_card_unlocks_card_idx on public.fan_card_unlocks(fan_card_id);
alter table public.fan_card_unlocks enable row level security;
revoke all on public.fan_card_unlocks from anon, authenticated;
grant select on public.fan_card_unlocks to authenticated;
grant insert (user_id, fan_card_id) on public.fan_card_unlocks to authenticated;
create policy fan_card_unlocks_owner_read on public.fan_card_unlocks
  for select to authenticated using (user_id = (select auth.uid()));
create policy fan_card_unlocks_owner_insert on public.fan_card_unlocks
  for insert to authenticated with check (user_id = (select auth.uid()));

INSERT INTO supabase_migrations.schema_migrations(version, name) VALUES ('20261016001000', 'fan_card_unlocks');

